import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BU4O3IzQ.js";const m=JSON.parse('{"title":"AI 动态 · 2026-07-28","description":"","frontmatter":{"title":"AI 动态 · 2026-07-28","date":"2026-07-28T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-07/ai-news-2026-07-28.md","filePath":"news/2026-07/ai-news-2026-07-28.md","lastUpdated":1786092171000}'),i={name:"news/2026-07/ai-news-2026-07-28.md"};function r(o,e,c,l,p,h){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-07-28" tabindex="-1">AI 动态 · 2026-07-28 <a class="header-anchor" href="#ai-动态-·-2026-07-28" aria-label="Permalink to &quot;AI 动态 · 2026-07-28&quot;">​</a></h1><blockquote><p>截至 2026-07-28。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="翁荔因健康原因离职thinking-machines" tabindex="-1">翁荔因健康原因离职Thinking Machines <a class="header-anchor" href="#翁荔因健康原因离职thinking-machines" aria-label="Permalink to &quot;翁荔因健康原因离职Thinking Machines&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-28">2026-07-28</time></p><p>北大校友、前OpenAI安全研究副总裁翁荔宣布将于明天离开她联合创立的AI公司Thinking Machines，距其加入仅20个月。她在公开信中表示，过去7个月生病次数比人生中任何时候都多，因高强度工作导致身体无法支撑。Thinking Machines刚于12天前发布首个开源模型Inkling。对读者：AI创业的高强度节奏对顶尖人才也是巨大考验，团队健康管理应纳入长期战略考量。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/461517.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="ilya获黄仁勋50亿美元押注-ssi与英伟达结盟" tabindex="-1">Ilya获黄仁勋50亿美元押注，SSI与英伟达结盟 <a class="header-anchor" href="#ilya获黄仁勋50亿美元押注-ssi与英伟达结盟" aria-label="Permalink to &quot;Ilya获黄仁勋50亿美元押注，SSI与英伟达结盟&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-28">2026-07-28</time></p><p>Ilya Sutskever旗下安全超级智能公司SSI宣布与英伟达达成长期合作，英伟达将授予下一代Vera Rubin平台使用权，预计一年内将SSI算力提升10倍。多家媒体报道投资金额约50亿美元。Ilya在X上表示“是时候开始Scaling了”。SSI自2024年6月成立以来估值已从50亿美元飙升至320亿美元。对读者：顶级AI人才与算力巨头的深度绑定，预示着安全超级智能赛道的军备竞赛正式升级。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/461911.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="全球首个agentic扩散模型llada2-2开源-蚂蚁旗下inclusionai发布" tabindex="-1">全球首个Agentic扩散模型LLaDA2.2开源，蚂蚁旗下inclusionAI发布 <a class="header-anchor" href="#全球首个agentic扩散模型llada2-2开源-蚂蚁旗下inclusionai发布" aria-label="Permalink to &quot;全球首个Agentic扩散模型LLaDA2.2开源，蚂蚁旗下inclusionAI发布&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-28">2026-07-28</time></p><p>蚂蚁集团旗下inclusionAI团队开源LLaDA2.2，这是全球首个大规模Agentic扩散模型。该模型为千亿参数MoE架构，原生支持128K上下文，首次将Levenshtein编辑、面向环境反馈的强化学习与长上下文工程整合进扩散模型Agent系统，实现边行动边纠错。LLaDA系列半年内迭代三代，证明扩散模型在长程Agent任务中可追平自回归模型。对读者：扩散模型在Agent赛道打破自回归垄断，开发者可关注其在并行生成与动态修正场景的工程优势。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/461650.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="kimi-k3与unlimited-ocr包揽hugging-face全球前二-中国开源模型刷屏" tabindex="-1">Kimi K3与Unlimited OCR包揽Hugging Face全球前二，中国开源模型刷屏 <a class="header-anchor" href="#kimi-k3与unlimited-ocr包揽hugging-face全球前二-中国开源模型刷屏" aria-label="Permalink to &quot;Kimi K3与Unlimited OCR包揽Hugging Face全球前二，中国开源模型刷屏&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-28">2026-07-28</time></p><p>月之暗面开源Kimi K3完整模型权重后迅速登顶Hugging Face总趋势榜第一，百度Unlimited OCR紧随其后位列第二。Kimi K3为2.8万亿参数MoE模型，支持100万token上下文；Unlimited OCR凭借Reference Sliding Window Attention机制解决长文档解析KV Cache膨胀问题，5天GitHub Star破万，获图灵奖得主杨立昆转发。对读者：中国开源模型在长上下文与文档解析领域取得突破，开发者可优先评估这两款模型在各自场景的落地成本。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/461949.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="豆包搜索开放给agent-火山引擎推出搜索api与mcp能力" tabindex="-1">豆包搜索开放给Agent，火山引擎推出搜索API与MCP能力 <a class="header-anchor" href="#豆包搜索开放给agent-火山引擎推出搜索api与mcp能力" aria-label="Permalink to &quot;豆包搜索开放给Agent，火山引擎推出搜索API与MCP能力&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-28">2026-07-28</time></p><p>火山引擎将豆包APP背后的搜索能力独立拆出，通过API、MCP、Skill等方式开放给企业和开发者。豆包搜索不仅返回网页链接，还附带信源名称、权威分级、发布时间、正文摘要及原文Markdown节选，便于Agent直接使用。每月赠送500次免费搜索额度，支持按量后付费和订阅月卡。对读者：Agent获取实时信息的门槛进一步降低，开发者可结合豆包搜索Skill快速为Agent注入可靠的外部知识检索能力。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/461961.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="索尼抛弃实体游戏光盘-全面转向数字发行" tabindex="-1">索尼抛弃实体游戏光盘，全面转向数字发行 <a class="header-anchor" href="#索尼抛弃实体游戏光盘-全面转向数字发行" aria-label="Permalink to &quot;索尼抛弃实体游戏光盘，全面转向数字发行&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">少数派</span><time datetime="2026-07-28">2026-07-28</time></p><p><img src="https://rssfile.sspai.com/2026/07/27/3e6ef2d104e10467c6b25c66289197af.jpg?imageMogr2/auto-orient/format/webp/ignore-error/1" alt="配图"></p><p>索尼PlayStation业务占据公司总营收约37.55%、利润约32.11%，为巩固平台经济优势，索尼决定彻底抛弃实体光盘。此举将摧毁消费者长期建立的二手交易与收藏体系，但符合资本市场对订阅制与数字生态的偏好。2025财年索尼游戏与网络服务营收约310亿美元，利润约31亿美元。对读者：数字发行已成不可逆趋势，游戏开发者和发行商需提前布局纯数字渠道的定价与用户运营策略。</p><p class="news-entry-source"><a href="https://sspai.com/post/112774" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="微软开源ai-agent治理工具包-覆盖owasp-agentic-top-10" tabindex="-1">微软开源AI Agent治理工具包，覆盖OWASP Agentic Top 10 <a class="header-anchor" href="#微软开源ai-agent治理工具包-覆盖owasp-agentic-top-10" aria-label="Permalink to &quot;微软开源AI Agent治理工具包，覆盖OWASP Agentic Top 10&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">microsoft/agent-governance-toolkit</span><time datetime="2026-07-28">2026-07-28</time></p><p><img src="https://opengraph.githubassets.com/1/microsoft/agent-governance-toolkit" alt="配图"></p><p>微软发布agent-governance-toolkit开源项目，提供策略执行、零信任身份、执行沙箱及可靠性工程等能力，全面覆盖OWASP Agentic Top 10安全风险。该项目旨在为自治AI Agent提供企业级治理框架，确保Agent在复杂环境中的安全可控运行。对读者：构建生产级Agent系统时，可直接复用该工具包的安全与治理模块，避免从零设计合规方案。</p><p class="news-entry-source"><a href="https://github.com/microsoft/agent-governance-toolkit" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="book-to-skill-将技术pdf一键转为claude-code技能" tabindex="-1">book-to-skill：将技术PDF一键转为Claude Code技能 <a class="header-anchor" href="#book-to-skill-将技术pdf一键转为claude-code技能" aria-label="Permalink to &quot;book-to-skill：将技术PDF一键转为Claude Code技能&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">virgiliojr94/book-to-skill</span><time datetime="2026-07-28">2026-07-28</time></p><p><img src="https://opengraph.githubassets.com/1/virgiliojr94/book-to-skill" alt="配图"></p><p>开源项目book-to-skill可将任意技术书籍PDF转换为Claude Code技能，转换后的技能可直接在编码工作中用于学习、参考和使用。该项目降低了将离线知识整合到AI编码助手工作流的门槛。对读者：技术团队可将内部文档或经典教材快速转化为可交互的AI技能，提升编码助手在特定领域的上下文理解能力。</p><p class="news-entry-source"><a href="https://github.com/virgiliojr94/book-to-skill" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="hugging-face开源speech-to-speech-构建本地语音agent" tabindex="-1">Hugging Face开源speech-to-speech，构建本地语音Agent <a class="header-anchor" href="#hugging-face开源speech-to-speech-构建本地语音agent" aria-label="Permalink to &quot;Hugging Face开源speech-to-speech，构建本地语音Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">huggingface/speech-to-speech</span><time datetime="2026-07-28">2026-07-28</time></p><p><img src="https://opengraph.githubassets.com/1/huggingface/speech-to-speech" alt="配图"></p><p>Hugging Face发布speech-to-speech开源项目，支持使用开源模型在本地构建语音Agent。该项目提供完整的端到端语音交互能力，无需依赖云端API即可实现语音识别、理解和合成。对读者：隐私敏感或离线场景下的语音交互应用可基于此项目快速搭建，避免第三方语音服务的依赖与成本。</p><p class="news-entry-source"><a href="https://github.com/huggingface/speech-to-speech" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="ecc-面向多agent编码助手的性能优化系统" tabindex="-1">ECC：面向多Agent编码助手的性能优化系统 <a class="header-anchor" href="#ecc-面向多agent编码助手的性能优化系统" aria-label="Permalink to &quot;ECC：面向多Agent编码助手的性能优化系统&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">affaan-m/ECC</span><time datetime="2026-07-28">2026-07-28</time></p><p><img src="https://opengraph.githubassets.com/1/affaan-m/ECC" alt="配图"></p><p>开源项目ECC（Enhanced Coding Companion）提供技能、本能、记忆、安全及研究优先开发等能力，专为Claude Code、Codex、Opencode、Cursor等Agent编码助手设计。该项目旨在优化Agent harness性能，提升多工具协同场景下的开发效率。对读者：重度使用AI编码助手的开发者可集成ECC来管理技能与记忆，减少重复配置并提升Agent响应质量。</p><p class="news-entry-source"><a href="https://github.com/affaan-m/ECC" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="kando-ai完成数千万元种子轮融资-要做-决策领域的cursor" tabindex="-1">Kando AI完成数千万元种子轮融资，要做“决策领域的Cursor” <a class="header-anchor" href="#kando-ai完成数千万元种子轮融资-要做-决策领域的cursor" aria-label="Permalink to &quot;Kando AI完成数千万元种子轮融资，要做“决策领域的Cursor”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">36氪</span><time datetime="2026-07-28">2026-07-28</time></p><p><img src="https://img.36krcdn.com/hsossms/20260728/v2_682a0c37d76b48f182b893d2a2f6a15b@000000_oswg34364oswg900oswg383_img_000?x-oss-process=image/resize,m_mfit,w_600,h_400,limit_0/crop,w_600,h_400,g_center" alt="配图"></p><p>Kando AI由北大计算机博士吴秉哲与连续创业者毛书翰联合创立，已完成数千万元种子轮融资，星连资本领投。公司致力于构建自进化决策系统，让AI从真实决策及其结果中持续学习，首期聚焦二级市场投资场景。团队来自腾讯、字节、美团等头部机构。对读者：关注AI在金融决策领域的落地，Kando AI的“认知数字化”思路可能重塑投研工作流。</p><p class="news-entry-source"><a href="https://36kr.com/p/3915057199535233?f=rss" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="gitlab将碳足迹意识融入ci-cd-衡量软件交付环境成本" tabindex="-1">GitLab将碳足迹意识融入CI/CD，衡量软件交付环境成本 <a class="header-anchor" href="#gitlab将碳足迹意识融入ci-cd-衡量软件交付环境成本" aria-label="Permalink to &quot;GitLab将碳足迹意识融入CI/CD，衡量软件交付环境成本&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-07-28">2026-07-28</time></p><p><img src="https://static001.infoq.cn/resource/image/c7/97/c79357bffcecb086265108d34b5ca097.jpg" alt="配图"></p><p>GitLab推出“绿色DevOps”方法，通过关联管道执行时长、执行器利用率、计算资源及区域电网碳强度，估算CI/CD管道产生的碳排放量。该功能将碳排放作为软件质量的可量化维度，帮助团队在不改变开发方式的前提下优化环境表现。智能缓存、并行执行、构建产物复用等优化可同时降低成本和碳排放。对读者：工程团队可借此将可持续性纳入DevOps指标，在优化效率的同时满足ESG合规要求。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/hJjOFog5ObigvYFod90j?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="快手完成从clickhouse到apache-doris的百pb级迁移" tabindex="-1">快手完成从ClickHouse到Apache Doris的百PB级迁移 <a class="header-anchor" href="#快手完成从clickhouse到apache-doris的百pb级迁移" aria-label="Permalink to &quot;快手完成从ClickHouse到Apache Doris的百PB级迁移&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-07-28">2026-07-28</time></p><p><img src="https://static001.infoq.cn/resource/image/42/8a/427c6ab108c8579c05cd7c012f52c58a.png" alt="配图"></p><p>快手基于Apache Doris构建“星移”自动化迁移平台，完成百PB级数据、200+ClickHouse集群向Doris的平滑迁移，支撑日均20亿OLAP查询。迁移解决了ClickHouse在Join能力、湖仓一体、存算分离及运维复杂度方面的局限，实现了DDL转换、任务复制、存量数据迁移全流程自动化。对读者：大规模OLAP场景下，Doris在复杂查询与统一底座方面的优势值得评估，尤其适合有多表Join和湖仓需求的团队。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/1YYoykV4gk0eRGE5HpTO?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const d=a(i,[["render",r]]);export{m as __pageData,d as default};
